type AnyRecord = Record<string, unknown>;

export interface SanitizedBackup {
    sync: AnyRecord;
    local: AnyRecord;
}

const ACTION_TYPES = new Set(["skip", "mute", "chapter", "full", "poi"]);
const PROFILE_BOOL_KEYS = [
    "showAutogeneratedChapters",
    "showCreatorChapters",
    "autoSkipOnMusicVideos",
    "skipNonMusicOnlyOnYoutubeMusic",
    "muteSegments",
    "fullVideoSegments",
    "manualSkipOnFullVideo",
] as const;

function plain(value: unknown): value is AnyRecord {
    if (!value || typeof value !== "object" || Array.isArray(value)) return false;
    const prototype = Object.getPrototypeOf(value);
    return prototype === Object.prototype || prototype === null;
}

function finiteNonnegative(value: unknown): value is number {
    return typeof value === "number" && Number.isFinite(value) && value >= 0;
}

function categories(value: unknown): AnyRecord[] | null {
    if (!Array.isArray(value)) return null;
    const output: AnyRecord[] = [];
    for (const item of value) {
        if (!plain(item)
            || typeof item.name !== "string"
            || item.name.length === 0
            || item.name.length > 80
            || !Number.isInteger(item.option)
            || (item.option as number) < -2
            || (item.option as number) > 2) return null;
        output.push({ name: item.name, option: item.option });
    }
    return output;
}

function profiles(value: unknown): AnyRecord | null {
    if (!plain(value)) return null;
    const output: AnyRecord = {};
    for (const [id, rawProfile] of Object.entries(value)) {
        if (!id || id.length > 200 || !plain(rawProfile)) return null;
        const categorySelections = categories(rawProfile.categorySelections);
        if (typeof rawProfile.name !== "string"
            || rawProfile.name.length === 0
            || rawProfile.name.length > 100
            || !categorySelections) return null;
        const profile: AnyRecord = { name: rawProfile.name, categorySelections };
        for (const key of PROFILE_BOOL_KEYS) {
            const current = rawProfile[key];
            if (current !== null && typeof current !== "boolean") return null;
            profile[key] = current;
        }
        if (rawProfile.minDuration !== null && !finiteNonnegative(rawProfile.minDuration)) return null;
        profile.minDuration = rawProfile.minDuration;
        output[id] = profile;
    }
    return output;
}

function segments(value: unknown): AnyRecord | null {
    if (!plain(value)) return null;
    const output: AnyRecord = {};
    for (const [videoID, rawSegments] of Object.entries(value)) {
        if (!videoID || videoID.length > 200 || !Array.isArray(rawSegments)) return null;
        const cleaned: AnyRecord[] = [];
        for (const raw of rawSegments) {
            if (!plain(raw)
                || !Array.isArray(raw.segment)
                || raw.segment.length !== 2
                || !finiteNonnegative(raw.segment[0])
                || !finiteNonnegative(raw.segment[1])
                || raw.segment[1] <= raw.segment[0]
                || typeof raw.UUID !== "string"
                || raw.UUID.length === 0
                || raw.UUID.length > 200
                || typeof raw.category !== "string"
                || raw.category.length === 0
                || raw.category.length > 80
                || typeof raw.actionType !== "string"
                || !ACTION_TYPES.has(raw.actionType)
                || !finiteNonnegative(raw.source)) return null;
            const segment: AnyRecord = {
                segment: [raw.segment[0], raw.segment[1]],
                UUID: raw.UUID,
                category: raw.category,
                actionType: raw.actionType,
                source: raw.source,
            };
            if (raw.description !== undefined) {
                if (typeof raw.description !== "string" || raw.description.length > 1000) return null;
                segment.description = raw.description;
            }
            cleaned.push(segment);
        }
        output[videoID] = cleaned;
    }
    return output;
}

function podcast(value: unknown): AnyRecord | null {
    if (!plain(value)
        || typeof value.enabled !== "boolean"
        || typeof value.titlePattern !== "string"
        || value.titlePattern.length > 500
        || !finiteNonnegative(value.introSeconds)
        || value.introSeconds > 600
        || !finiteNonnegative(value.outroSeconds)
        || value.outroSeconds > 600) return null;
    return {
        enabled: value.enabled,
        titlePattern: value.titlePattern,
        introSeconds: value.introSeconds,
        outroSeconds: value.outroSeconds,
    };
}

export function sanitizeBackup(value: unknown): SanitizedBackup | null {
    if (!plain(value)
        || value.format !== "skiplist-personal-1"
        || !plain(value.sync)
        || !plain(value.local)) return null;

    const sync: AnyRecord = {};
    const local: AnyRecord = {};
    for (const counter of ["minutesSaved", "skipCount"] as const) {
        if (!finiteNonnegative(value.sync[counter])) return null;
        sync[counter] = value.sync[counter];
    }
    const categorySelections = categories(value.sync.categorySelections);
    if (!categorySelections) return null;
    sync.categorySelections = categorySelections;

    const unsubmittedSegments = segments(value.local.unsubmittedSegments);
    const skipProfiles = profiles(value.local.skipProfiles);
    const podcastRules = podcast(value.local.podcastRules);
    if (!unsubmittedSegments || !skipProfiles || !podcastRules) return null;
    local.unsubmittedSegments = unsubmittedSegments;
    local.skipProfiles = skipProfiles;
    local.podcastRules = podcastRules;
    return { sync, local };
}
